{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Alvimopan, a zwitterionic piperidine carboxylic acid with a basic amine, has an absolute oral bioavailability of only 6% in humans; this is the closest analogue sharing the query's acid/amine zwitterionic character and directly supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Cilomilast, which shares the cyclohexane-carbonitrile-carboxylic acid motif, is almost completely bioavailable (96%) in humans; however, it lacks the basic amine that makes the query zwitterionic, so this high-F evidence is less transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C44"],
      "claim": "Melperone, a basic piperidine without a carboxylic acid, has an absolute bioavailability of 54% in humans; it supports high F but lacks the acid/zwitterion and is therefore a weaker transfer.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low oral bioavailability. The query is a zwitterionic piperidine carboxylic acid with essentially zero neutral fraction at pH 7.4, a profile associated with poor permeability. The most mechanistically transferable analogue, alvimopan (F=6% in humans), is also a zwitterionic piperidine acid and demonstrates low F. Cilomilast's high F (96%) is less transferable because it lacks the basic amine, and other high-F basic-amine analogues lack the carboxylic acid.",
  "evidence_gaps": [
    "No direct human or animal pharmacokinetic data for the query molecule.",
    "No experimental permeability (e.g., Caco-2/PAMPA) or transporter-efflux data.",
    "No experimentally measured pKa/logD/neutral fraction for the query.",
    "No dose, formulation, or food-effect data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

